<?php require_once '../includes/auth.php';require_admin();verify_csrf();if(!isset($_FILES['file'])||$_FILES['file']['error'])exit('Upload failed');$f=$_FILES['file'];if($f['size']>10*1024*1024)exit('Maximum file size is 10 MB.');$ext=strtolower(pathinfo($f['name'],PATHINFO_EXTENSION));$allowed=['pdf','doc','docx','xls','xlsx','csv','ppt','pptx','txt'];if(!in_array($ext,$allowed,true))exit('Format not allowed');$stored=bin2hex(random_bytes(16)).'.'.$ext;$dir=__DIR__.'/../uploads';if(!is_dir($dir))mkdir($dir,0750,true);if(!move_uploaded_file($f['tmp_name'],$dir.'/'.$stored))exit('Could not store file');$s=mysqli_prepare($conn,"INSERT INTO letter_templates(name,category,original_name,stored_name,mime_type,file_size,uploaded_by) VALUES(?,?,?,?,?,?,?)");$name=trim($_POST['name']??'');$cat=$_POST['category']??'official_letter';$mime=mime_content_type($dir.'/'.$stored);$uid=user()['id'];mysqli_stmt_bind_param($s,'ssssssi',$name,$cat,$f['name'],$stored,$mime,$f['size'],$uid);mysqli_stmt_execute($s);log_activity('created','templates',$name,mysqli_insert_id($conn));flash('success','Format uploaded.');redirect('list.php');
